class Solution:
    def maxGeneticDifference(self, parents: List[int], queries: List[List[int]]) -> List[int]:
        ans = []
        for node, val in queries:
            best = 0
            cur = node
            while cur != -1:
                best = max(best, val ^ cur)
                cur = parents[cur]
            ans.append(best)
        return ans

