class Solution {
public:
    vector<int> maxGeneticDifference(vector<int>& parents, vector<vector<int>>& queries) {
        vector<int> ans;
        ans.reserve(queries.size());
        for (auto& q : queries) {
            int best = 0;
            for (int cur = q[0]; cur != -1; cur = parents[cur])
                best = max(best, q[1] ^ cur);
            ans.push_back(best);
        }
        return ans;
    }
};

