from collections import defaultdict

class Solution:
    def maxGeneticDifference(self, parents: List[int], queries: List[List[int]]) -> List[int]:
        n = len(parents)
        children = [[] for _ in range(n)]
        root = 0
        for v, p in enumerate(parents):
            if p == -1:
                root = v
            else:
                children[p].append(v)

        queries_at = defaultdict(list)
        for i, (node, val) in enumerate(queries):
            queries_at[node].append((i, val))

        BITS = 18
        ch = [[0, 0]]
        cnt = [0]

        def update(v, delta):
            cur = 0
            for b in range(BITS - 1, -1, -1):
                bit = (v >> b) & 1
                if not ch[cur][bit]:
                    ch.append([0, 0])
                    cnt.append(0)
                    ch[cur][bit] = len(ch) - 1
                cur = ch[cur][bit]
                cnt[cur] += delta

        def query(v):
            cur, res = 0, 0
            for b in range(BITS - 1, -1, -1):
                bit = (v >> b) & 1
                if ch[cur][1 - bit] and cnt[ch[cur][1 - bit]]:
                    res |= 1 << b
                    cur = ch[cur][1 - bit]
                else:
                    cur = ch[cur][bit]
            return res

        ans = [0] * len(queries)
        stack = [(root, 0)]
        while stack:
            node, phase = stack.pop()
            if phase == 1:
                update(node, -1)
                continue
            update(node, 1)
            for i, val in queries_at.get(node, ()):
                ans[i] = query(val)
            stack.append((node, 1))
            for c in children[node]:
                stack.append((c, 0))
        return ans

