class Solution {
public:
    vector<int> maxGeneticDifference(vector<int>& parents, vector<vector<int>>& queries) {
        int n = parents.size();
        vector<vector<int>> children(n);
        int root = 0;
        for (int v = 0; v < n; ++v) {
            if (parents[v] == -1) root = v;
            else children[parents[v]].push_back(v);
        }
        int q = queries.size();
        vector<vector<pair<int,int>>> queriesAt(n);
        for (int i = 0; i < q; ++i)
            queriesAt[queries[i][0]].push_back({i, queries[i][1]});

        const int BITS = 18;
        int maxNodes = n * BITS + 2;
        vector<array<int,2>> ch(maxNodes, {0, 0});
        vector<int> cnt(maxNodes, 0);
        int sz = 1;

        auto update = [&](int v, int delta) {
            int cur = 0;
            for (int b = BITS - 1; b >= 0; --b) {
                int bit = (v >> b) & 1;
                if (!ch[cur][bit]) {
                    ch[sz] = {0, 0};
                    cnt[sz] = 0;
                    ch[cur][bit] = sz++;
                }
                cur = ch[cur][bit];
                cnt[cur] += delta;
            }
        };
        auto query = [&](int v) {
            int cur = 0, res = 0;
            for (int b = BITS - 1; b >= 0; --b) {
                int bit = (v >> b) & 1;
                if (ch[cur][1 - bit] && cnt[ch[cur][1 - bit]]) {
                    res |= 1 << b;
                    cur = ch[cur][1 - bit];
                } else {
                    cur = ch[cur][bit];
                }
            }
            return res;
        };

        vector<int> ans(q);
        vector<pair<int,int>> st;
        st.push_back({root, 0});
        while (!st.empty()) {
            auto [node, phase] = st.back();
            st.pop_back();
            if (phase) { update(node, -1); continue; }
            update(node, 1);
            for (auto& [idx, val] : queriesAt[node]) ans[idx] = query(val);
            st.push_back({node, 1});
            for (int c : children[node]) st.push_back({c, 0});
        }
        return ans;
    }
};

