class Solution {
    private int[][] ch;
    private int[] cnt;
    private int sz;

    public int[] maxGeneticDifference(int[] parents, int[][] queries) {
        int n = parents.length;
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        int root = 0;
        for (int v = 0; v < n; v++) {
            if (parents[v] == -1) root = v;
            else children.get(parents[v]).add(v);
        }
        int q = queries.length;
        Map<Integer, List<int[]>> queriesAt = new HashMap<>();
        for (int i = 0; i < q; i++)
            queriesAt.computeIfAbsent(queries[i][0], k -> new ArrayList<>())
                     .add(new int[]{i, queries[i][1]});

        final int BITS = 18;
        ch = new int[n * BITS + 2][2];
        cnt = new int[n * BITS + 2];
        sz = 1;

        int[] ans = new int[q];
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{root, 0});
        while (!stack.isEmpty()) {
            int[] top = stack.pop();
            int node = top[0], phase = top[1];
            if (phase == 1) {
                update(node, -1);
                continue;
            }
            update(node, 1);
            List<int[]> qs = queriesAt.get(node);
            if (qs != null)
                for (int[] qu : qs) ans[qu[0]] = query(qu[1]);
            stack.push(new int[]{node, 1});
            for (int c : children.get(node)) stack.push(new int[]{c, 0});
        }
        return ans;
    }

    private void update(int v, int delta) {
        int cur = 0;
        for (int b = 17; b >= 0; b--) {
            int bit = (v >> b) & 1;
            if (ch[cur][bit] == 0) ch[cur][bit] = sz++;
            cur = ch[cur][bit];
            cnt[cur] += delta;
        }
    }

    private int query(int v) {
        int cur = 0, res = 0;
        for (int b = 17; b >= 0; b--) {
            int bit = (v >> b) & 1;
            if (ch[cur][1 - bit] != 0 && cnt[ch[cur][1 - bit]] > 0) {
                res |= 1 << b;
                cur = ch[cur][1 - bit];
            } else {
                cur = ch[cur][bit];
            }
        }
        return res;
    }
};

