var maxGeneticDifference = function(parents, queries) {
    const n = parents.length;
    const children = Array.from({length: n}, () => []);
    let root = 0;
    for (let v = 0; v < n; v++) {
        if (parents[v] === -1) root = v;
        else children[parents[v]].push(v);
    }
    const queriesAt = new Map();
    queries.forEach(([node, val], i) => {
        if (!queriesAt.has(node)) queriesAt.set(node, []);
        queriesAt.get(node).push([i, val]);
    });

    const BITS = 18;
    const total = n * BITS + 2;
    const ch = Array.from({length: total}, () => [0, 0]);
    const cnt = new Array(total).fill(0);
    let sz = 1;

    const update = (v, delta) => {
        let cur = 0;
        for (let b = BITS - 1; b >= 0; b--) {
            const bit = (v >> b) & 1;
            if (!ch[cur][bit]) ch[cur][bit] = sz++;
            cur = ch[cur][bit];
            cnt[cur] += delta;
        }
    };
    const query = (v) => {
        let cur = 0, res = 0;
        for (let b = BITS - 1; b >= 0; b--) {
            const bit = (v >> b) & 1;
            if (ch[cur][1 - bit] && cnt[ch[cur][1 - bit]] > 0) {
                res |= 1 << b;
                cur = ch[cur][1 - bit];
            } else {
                cur = ch[cur][bit];
            }
        }
        return res;
    };

    const ans = new Array(queries.length);
    const stack = [[root, 0]];
    while (stack.length) {
        const [node, phase] = stack.pop();
        if (phase === 1) { update(node, -1); continue; }
        update(node, 1);
        const qs = queriesAt.get(node);
        if (qs) for (const [i, val] of qs) ans[i] = query(val);
        stack.push([node, 1]);
        for (const c of children[node]) stack.push([c, 0]);
    }
    return ans;
};
